pub fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    // sep is guaranteed non-empty by the problem statement.
    let maxsplit_usize = maxsplit as usize;

    a.into_iter()
        .map(|s| {
            if maxsplit_usize == 0 {
                return vec![s];
            }

            // Repeatedly peel off suffixes from the right.
            let mut parts_rev: Vec<String> = Vec::new();
            let mut rest: &str = &s;
            let mut splits_done: usize = 0;

            while splits_done < maxsplit_usize {
                if let Some(idx) = rest.rfind(&sep) {
                    let after = idx + sep.len();
                    // Push the rightmost piece (after the separator).
                    parts_rev.push(rest[after..].to_string());
                    // Continue searching in the left part.
                    rest = &rest[..idx];
                    splits_done += 1;
                } else {
                    break;
                }
            }

            // Whatever remains on the left is always included (may be empty).
            parts_rev.push(rest.to_string());

            // Reverse to restore left-to-right order.
            parts_rev.reverse();
            parts_rev
        })
        .collect()
}